        elif m == "add" and len(ops) == 2 and ops[0].type == 1 and ops[1].type == 2:
            dst = canonical(ops[0].reg)
            if origins.get(dst) is not None:
                origin = origins[dst]
                origins[dst] = (origin[0], origin[1] + int(ops[1].imm))
