by={}
for va,i in g.instructions.items():
 for op in i.operands:
  if op.type==CS_OP_IMM and 0<=op.imm<1<<32:
   try:c=op.imm.to_bytes(4,"big").decode("ascii")
   except:continue
   if len(c)==4 and all(32<=ord(x)<127 for x in c):by.setdefault(c,[]).append(va)
for f in fm["fields"]:
 if f["status"]!="unmapped" or f["code"] not in by:continue
 c=f["code"]; outs=[]
 for va in by[c]:
