  j=g.instructions[nx]; st=j.operands[0].imm if j.mnemonic.startswith("j") and j.mnemonic!="jmp" and (j.mnemonic=="je") else (nx+j.size if j.mnemonic=="jne" else None)
  if st is None:continue
  todo=[(0,st)];seen=set();found=[]
  while todo and len(seen)<1200:
   d,a=heapq.heappop(todo)
   if a in seen or d>35:continue
   seen.add(a);z=g.instructions.get(a)
   if z is None:continue
   for op in z.operands:
    if op.type==CS_OP_MEM and md.reg_name(op.mem.base)=="r12":found.append((d,p.va2f(a),z.mnemonic,z.op_str,op.mem.disp))
   if z.mnemonic in ("ret","retf","iret","int3","ud2"):continue
   for q in g.successors.get(a,[]):
    heapq.heappush(todo,(d+1,q))
  if found:outs.append((p.va2f(va),sorted(found)[:3]))
 print(f["xml_index"],c,f["schema"].get("name"),"CMP",[(hex(a),[(d,hex(o),m,s,hex(disp)) for d,o,m,s,disp in rows]) for a,rows in outs])'

