def profile(f,join,b,cells,keys):
    import calendar
    fmt,arg=join['format'],join['arg']; lo=f.get('min_value');hi=f.get('max_value'); er=f.get('enum_ref')
    target=keys.get(arg,{}) if fmt=='ref' else {}; wrong=set(target.values())
