    assert sum(status.values())==255
    desc=[]; templates={s:[dict(rows=n,sequence=list(seq)) for seq,n in runs[s][2].most_common()] for s in SIDES}
    for k,a,w,m in SPEC:
        cells=runs['client'][1].get(k,[]); legacy_steps=[]
