HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[2]
T59 = ROOT/'scratch/t59/out'
TABLES = (2,3,10,21,25)
NAMES = dict(vec30=('vec30',None), vec18=('vec18',None))
NAMES.update({f'+0x{k}':(f'obj_{k}',f'{k}_present') for k in ('a8','e0','e8','c0','c8','d0','d8')})
