                "classification": "conditional_payload_helper",
                "role": label,
                "member_offset": member,
                "xml_consumers": [],
                "observed_entry_count": 0,
            })
        elif slot:
            item.update({
                "slot": slot["key"],
                "member_offset": slot.get("object_offset"),
                "classification": "existing_slot_helper" if consumers(slot) else "unmapped_slot_helper",
            })
        calls.append(item)

